let deferredInstall=null,registration=null,ready=false,waiting=false;
const button=document.createElement('button');button.textContent='Instalar / offline';button.id='installGame';document.querySelector('#menu nav').append(button);
const status=document.createElement('small');status.id='offlineState';status.textContent='Preparando arquivos para jogar offline…';document.querySelector('#menu').append(status);
const dialog=document.createElement('dialog');dialog.id='offlineDialog';dialog.innerHTML='<button id="closeOffline" aria-label="Fechar">×</button><div class="eyebrow">SEU JOGO NO CELULAR</div><h2>Leve este mundo com você.</h2><p id="offlineDetail">Aguarde o download inicial com internet. O jogo confirmará quando os arquivos estiverem guardados.</p><p id="installInstructions">No Android, use a opção de instalar do navegador. No iPhone, abra no Safari e use Compartilhar → Adicionar à Tela de Início → Adicionar.</p><button id="nativeInstall" class="primary" hidden>Instalar no celular</button><button id="applyUpdate" class="primary" hidden>Atualizar e reabrir o jogo</button><p class="guideFoot">Para abrir sem internet, aguarde a confirmação e use o ícone da tela inicial. Progresso e desenhos ficam neste aparelho. Limpar os dados do navegador pode removê-los.</p>';document.body.append(dialog);
const detail=dialog.querySelector('#offlineDetail'),nativeInstall=dialog.querySelector('#nativeInstall'),applyUpdate=dialog.querySelector('#applyUpdate');
function render(){status.textContent=waiting?'Atualização disponível para o jogo.':ready?'Pronto para jogar offline.':navigator.onLine?'Preparando arquivos para jogar offline…':'Sem conexão. Conecte para concluir o primeiro download.';detail.textContent=ready?'Os arquivos do jogo estão salvos. Depois de adicionar à tela inicial, você pode abrir sem internet. Música, cartas e fases também ficam disponíveis.':'Abra com internet e aguarde “Pronto para jogar offline”. O download inicial precisa terminar antes de jogar sem conexão.';nativeInstall.hidden=!ready||!deferredInstall;applyUpdate.hidden=!waiting;}
button.onclick=()=>{render();dialog.showModal()};dialog.querySelector('#closeOffline').onclick=()=>dialog.close();
nativeInstall.onclick=async()=>{if(!deferredInstall)return;const event=deferredInstall;deferredInstall=null;await event.prompt();await event.userChoice;render()};
let reloading=false;applyUpdate.onclick=()=>{if(!registration?.waiting)return;reloading=true;registration.waiting.postMessage({type:'ACTIVATE_UPDATE'})};
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredInstall=event;render()});window.addEventListener('appinstalled',()=>{deferredInstall=null;render()});
function check(){const worker=navigator.serviceWorker?.controller||registration?.active;worker?.postMessage({type:'CHECK_OFFLINE'})}
if('serviceWorker'in navigator){navigator.serviceWorker.addEventListener('message',event=>{if(event.data?.type==='OFFLINE_STATUS'){ready=!!event.data.ready;render()}});navigator.serviceWorker.addEventListener('controllerchange',()=>{if(reloading){location.reload();return}check()});
check();async function register(){try{registration=await navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'});if(registration.waiting){waiting=true;render()}registration.addEventListener('updatefound',()=>{let worker=registration.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'){waiting=!!registration.waiting&&!!navigator.serviceWorker.controller;check();render()}if(worker.state==='redundant'&&!ready){status.textContent='Download offline não concluído. Reabra o jogo com internet para tentar novamente.';detail.textContent=status.textContent}})});await navigator.serviceWorker.ready;check();navigator.storage?.persist?.().catch(()=>{});}catch{if(ready)return;status.textContent='Não foi possível preparar o modo offline neste navegador.';detail.textContent='Tente abrir o link no Chrome ou Safari com internet e recarregue. Não feche o jogo antes da confirmação de download.'}}
if(document.readyState==='complete')register();else window.addEventListener('load',register,{once:true});window.addEventListener('online',()=>{render();registration?.update().catch(()=>{});check()});window.addEventListener('offline',()=>{render();check()});
}else{status.textContent='Este navegador não oferece suporte ao modo offline.';detail.textContent='Abra o jogo em um navegador atualizado para preparar o modo offline.'}
